/*
 * Pairwise model of an option schema (every pair of values appears in at least
 * one row of `pairwiseCases`; 26 rows, generated by a greedy all-pairs pass):
 *
 *   type:        none | string | number | boolean | string[] | number[]
 *   choices:     none | valid | empty | mismatched
 *   default:     none | valid | outside
 *   parse:       no | yes
 *   required:    no | yes
 *   placeholder: none | value | number
 *
 * `valid` choices are of the value type (`[1, 2]` or `["a", "b"]`), `mismatched`
 * ones of the other type. A `valid` default is in the choices, an `outside` one
 * is of the value type but not in them. The expected outcome of each row is
 * derived from the definition rules, not from the implementation.
 */
import { describe, expect, it } from "vitest";
import {
  CLIError,
  createCLI,
  InvalidOptionError,
  type OptionSchema,
  ValidationError,
} from "../src/index.js";
import { createMockStdout } from "./helpers.js";

type TypeLevel = "none" | "string" | "number" | "boolean" | "string[]" | "number[]";
type ChoicesLevel = "none" | "valid" | "empty" | "mismatched";
type DefaultLevel = "none" | "valid" | "outside";
type YesNo = "no" | "yes";
type PlaceholderLevel = "none" | "value" | "number";
type Case = [TypeLevel, ChoicesLevel, DefaultLevel, YesNo, YesNo, PlaceholderLevel];

const pairwiseCases: Case[] = [
  ["none", "none", "none", "no", "no", "none"],
  ["none", "valid", "valid", "yes", "yes", "value"],
  ["string", "empty", "outside", "no", "yes", "number"],
  ["number", "mismatched", "none", "yes", "no", "number"],
  ["boolean", "none", "outside", "yes", "no", "value"],
  ["boolean", "mismatched", "valid", "no", "yes", "none"],
  ["string[]", "empty", "valid", "yes", "no", "none"],
  ["string[]", "valid", "none", "no", "yes", "value"],
  ["number[]", "none", "valid", "no", "yes", "number"],
  ["number[]", "valid", "outside", "yes", "no", "none"],
  ["string", "empty", "none", "yes", "no", "value"],
  ["number", "mismatched", "outside", "no", "yes", "value"],
  ["boolean", "valid", "none", "no", "no", "number"],
  ["none", "empty", "outside", "no", "no", "number"],
  ["string", "none", "valid", "no", "no", "none"],
  ["number", "none", "valid", "no", "no", "none"],
  ["string[]", "none", "outside", "no", "no", "number"],
  ["number[]", "empty", "none", "no", "no", "value"],
  ["none", "mismatched", "none", "no", "no", "none"],
  ["string", "valid", "none", "no", "no", "none"],
  ["string", "mismatched", "none", "no", "no", "none"],
  ["number", "valid", "none", "no", "no", "none"],
  ["number", "empty", "none", "no", "no", "none"],
  ["boolean", "empty", "none", "no", "no", "none"],
  ["string[]", "mismatched", "none", "no", "no", "none"],
  ["number[]", "mismatched", "none", "no", "no", "none"],
];

/** The schema a row describes, plus what the definition rules say about it. */
function describeCase([type, choices, def, parse, required, placeholder]: Case) {
  const flags = { none: "--opt", value: "--opt <v>", number: "--opt <number>" }[placeholder];
  const effective = type !== "none" ? type : placeholder === "none" ? "boolean" : "string";
  const numeric = effective === "number" || effective === "number[]";
  const array = effective.endsWith("[]");
  const scalar = (n: number, s: string) => (numeric ? n : s);
  const wrap = (v: unknown) => (array ? [v] : v);

  const schema: OptionSchema = {};
  if (type !== "none") schema.type = type;
  if (choices === "valid") schema.choices = numeric ? [1, 2] : ["a", "b"];
  if (choices === "empty") schema.choices = [];
  if (choices === "mismatched") schema.choices = numeric ? ["1", "2"] : [1, 2];
  if (def !== "none") {
    schema.default =
      effective === "boolean"
        ? def === "valid"
        : wrap(def === "valid" ? scalar(2, "b") : scalar(9, "z"));
  }
  if (parse === "yes") schema.parse = (value) => `p:${value}`;
  if (required === "yes") schema.required = true;

  const invalid =
    (placeholder === "number" && !numeric) ||
    (required === "yes" && def !== "none") ||
    (choices !== "none" && (choices !== "valid" || parse === "yes" || effective === "boolean")) ||
    (choices === "valid" && def === "outside");

  const input = scalar(2, "b");
  const argv = effective === "boolean" ? ["run", "--opt"] : ["run", "--opt", String(input)];
  const given =
    parse === "yes"
      ? wrap(`p:${effective === "boolean" ? "true" : input}`)
      : effective === "boolean"
        ? true
        : wrap(input);
  const absent =
    required === "yes"
      ? { code: "MISSING_OPTION" }
      : def !== "none"
        ? { value: schema.default }
        : effective === "boolean"
          ? { value: false }
          : { missing: true };
  const rejected =
    choices === "valid" && !invalid ? ["run", "--opt", String(scalar(9, "z"))] : undefined;
  return { flags, schema, invalid, argv, given, absent, rejected };
}

function quiet() {
  const stream = createMockStdout();
  return { stdout: stream, stderr: stream };
}

function thrownBy(fn: () => unknown): unknown {
  try {
    fn();
  } catch (err) {
    return err;
  }
  return undefined;
}

/** Defines `run` with one option and returns a runner reporting what the action saw. */
function defineRun(flags: string, schema: OptionSchema) {
  const cli = createCLI({ name: "test" });
  let seen: { present: boolean; value: unknown } | undefined;
  cli
    .command("run")
    .option(flags, schema as never)
    .action((ctx) => {
      const options = ctx.options as Record<string, unknown>;
      seen = { present: Object.hasOwn(options, "opt"), value: options.opt };
    });
  return async (argv: string[]) => {
    seen = undefined;
    await cli.exec(argv, quiet());
    return seen as { present: boolean; value: unknown };
  };
}

describe("option schema pairwise", () => {
  it.each(pairwiseCases)(
    "type=%s choices=%s default=%s parse=%s required=%s placeholder=%s",
    async (...row) => {
      const { flags, schema, invalid, argv, given, absent, rejected } = describeCase(row);
      const builder = createCLI({ name: "test" }).command("run");
      const definition = thrownBy(() => builder.option(flags, schema as never));
      if (invalid) {
        expect(definition).toMatchObject({ code: "ERR_INVALID_DEFINITION" });
        return;
      }
      expect(definition).toBeUndefined();

      const run = defineRun(flags, schema);
      await expect(run(argv)).resolves.toEqual({ present: true, value: given });
      if ("code" in absent) {
        await expect(run(["run"])).rejects.toMatchObject({ code: absent.code });
      } else if ("missing" in absent) {
        await expect(run(["run"])).resolves.toEqual({ present: false, value: undefined });
      } else {
        await expect(run(["run"])).resolves.toEqual({ present: true, value: absent.value });
      }
      if (rejected) {
        await expect(run(rejected)).rejects.toBeInstanceOf(InvalidOptionError);
      }
    },
  );
});

describe("choices", () => {
  it("names the mismatched choice type", () => {
    const builder = createCLI({ name: "test" }).command("run");
    expect(() => builder.option("--n <n>", { type: "number", choices: ["1"] } as never)).toThrow(
      'Option "--n" declares a choice of type string but its type is number',
    );
  });

  it.each([
    ["NaN", Number.NaN],
    ["Infinity", Number.POSITIVE_INFINITY],
    ["-Infinity", Number.NEGATIVE_INFINITY],
    ["MAX_SAFE_INTEGER + 1", Number.MAX_SAFE_INTEGER + 1],
    ["-(MAX_SAFE_INTEGER + 1)", -(Number.MAX_SAFE_INTEGER + 1)],
  ])("rejects the numeric choice %s", (_, choice) => {
    const builder = createCLI({ name: "test" }).command("run");
    expect(
      thrownBy(() => builder.option("--n <n>", { type: "number", choices: [1, choice] })),
    ).toMatchObject({ code: "ERR_INVALID_DEFINITION" });
  });

  it.each([
    ["null", null],
    ["undefined", undefined],
    ["a boolean", true],
  ])("rejects %s as a choice", (_, choice) => {
    const builder = createCLI({ name: "test" }).command("run");
    expect(
      thrownBy(() => builder.option("--s <s>", { choices: ["a", choice] } as never)),
    ).toMatchObject({ code: "ERR_INVALID_DEFINITION" });
  });

  it("accepts the safe-integer bounds and matches -0 with 0", async () => {
    const run = defineRun("--opt <n>", {
      type: "number",
      choices: [0, Number.MAX_SAFE_INTEGER, -Number.MAX_SAFE_INTEGER],
    });
    await expect(run(["run", "--opt=-0"])).resolves.toMatchObject({ value: -0 });
    await expect(run(["run", "--opt", String(Number.MAX_SAFE_INTEGER)])).resolves.toMatchObject({
      value: Number.MAX_SAFE_INTEGER,
    });
  });

  it("matches the converted value, so a number option accepts any spelling of a choice", async () => {
    const run = defineRun("--opt <n>", { type: "number", choices: [1, 2] });
    await expect(run(["run", "--opt", "1.0"])).resolves.toMatchObject({ value: 1 });
    await expect(run(["run", "--opt", "1e0"])).resolves.toMatchObject({ value: 1 });
  });

  it("no longer matches a number choice against string input", () => {
    const builder = createCLI({ name: "test" }).command("run");
    expect(thrownBy(() => builder.option("--opt <s>", { choices: [1] } as never))).toMatchObject({
      code: "ERR_INVALID_DEFINITION",
    });
  });

  it("reports the rejected element of an array option, quoted", async () => {
    const run = defineRun("--opt <s>", { type: "string[]", choices: ["a", "b"] });
    const failure = run(["run", "--opt", "a", "--opt", 'z"q']);
    await expect(failure).rejects.toMatchObject({
      code: "INVALID_OPTION",
      optionName: "opt",
      value: 'z"q',
    });
    await expect(failure).rejects.toThrow('Invalid value "z\\"q" for --opt');
  });
});

describe("default", () => {
  it("keeps the built-in coercion of a default for JavaScript callers", async () => {
    const run = defineRun("--opt <n>", { type: "number", default: "8080" });
    await expect(run(["run"])).resolves.toEqual({ present: true, value: 8080 });
  });

  it("does not run parse on a default", async () => {
    const date = new Date(0);
    const run = defineRun("--opt <d>", { parse: (value) => new Date(value), default: date });
    await expect(run(["run"])).resolves.toEqual({ present: true, value: date });
  });
});

describe("option callback failures", () => {
  it("wraps a parse failure with the raw string, the option and the usage", async () => {
    const cause = new Error("not a port");
    const run = defineRun("--opt <p>", {
      parse: () => {
        throw cause;
      },
    });
    const err = await run(["run", "--opt", "x\ny"]).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(ValidationError);
    expect(err).toMatchObject({ optionName: "opt", value: "x\ny", cause, exitCode: 64 });
    expect((err as ValidationError).usage).toContain("run");
    expect((err as Error).message).toContain('Invalid value "x\\ny" for --opt: not a port');
  });

  it("reports the failing element of an array option's parse", async () => {
    const run = defineRun("--opt <p>", {
      type: "string[]",
      parse: async (value) => {
        if (value === "bad") throw "rejected";
        return value;
      },
    });
    const err = await run(["run", "--opt", "ok", "--opt", "bad"]).catch((e: unknown) => e);
    expect(err).toMatchObject({ code: "VALIDATION_FAILED", value: "bad", cause: "rejected" });
    expect((err as Error).message).toContain('Invalid value "bad" for --opt: rejected');
  });

  it("wraps a validate failure with the value validate received", async () => {
    const run = defineRun("--opt <n>", {
      type: "number",
      validate: () => {
        throw new Error("too big");
      },
    });
    const err = await run(["run", "--opt", "5"]).catch((e: unknown) => e);
    expect(err).toMatchObject({ code: "VALIDATION_FAILED", optionName: "opt", value: 5 });
    expect((err as Error).message).toContain("Invalid value 5 for --opt: too big");
  });

  it.each(["parse", "validate"])("lets a CLIError thrown by %s through unchanged", async (key) => {
    const thrown = new CLIError("custom", { code: "CUSTOM", exitCode: 3 });
    const schema: OptionSchema = {
      [key]: () => {
        throw thrown;
      },
    };
    const run = defineRun("--opt <v>", schema);
    await expect(run(["run", "--opt", "v"])).rejects.toBe(thrown);
  });

  it.each(["parse", "validate"])(
    "leaves a cancellation inside %s to the cancellation path",
    async (key) => {
      const cli = createCLI({ name: "test" });
      const controller = new AbortController();
      const waitForAbort = async (_: unknown, ctx: { signal: AbortSignal }) => {
        await new Promise((resolve) => ctx.signal.addEventListener("abort", resolve));
        throw ctx.signal.reason;
      };
      cli
        .command("run")
        .option("--opt <v>", { [key]: waitForAbort } as never)
        .action(() => {});
      const execution = cli.exec(["run", "--opt", "v"], { ...quiet(), signal: controller.signal });
      setImmediate(() => controller.abort());
      const err = await execution.catch((e: unknown) => e);
      expect(err).not.toBeInstanceOf(ValidationError);
      expect(["AbortError", "CancelledError"]).toContain((err as Error).name);
    },
  );
});

describe("command validate failures", () => {
  function defineValidated(validate: () => void | Promise<void>) {
    const cli = createCLI({ name: "test" });
    cli
      .command("deploy <env>")
      .validate(validate)
      .action(() => {});
    return () => cli.exec(["deploy", "prod"], quiet());
  }

  it("wraps a thrown Error in a ValidationError with the cause's message and the usage", async () => {
    const cause = new Error("prod is locked");
    const err = await defineValidated(() => {
      throw cause;
    })().catch((e: unknown) => e);
    expect(err).toBeInstanceOf(ValidationError);
    expect(err).toMatchObject({ code: "VALIDATION_FAILED", exitCode: 64, cause });
    expect((err as ValidationError).optionName).toBeUndefined();
    expect((err as ValidationError).value).toBeUndefined();
    expect((err as Error).message).toMatch(/^prod is locked\n\n {2}Usage: test deploy <env>/);
  });

  it("wraps a non-Error throw with its rendered message", async () => {
    const err = await defineValidated(() => {
      throw "nope";
    })().catch((e: unknown) => e);
    expect(err).toMatchObject({ code: "VALIDATION_FAILED", cause: "nope" });
    expect((err as Error).message).toMatch(/^nope/);
  });

  it("lets a CLIError through unchanged", async () => {
    const thrown = new CLIError("custom", { code: "CUSTOM" });
    await expect(
      defineValidated(async () => {
        throw thrown;
      })(),
    ).rejects.toBe(thrown);
  });

  it("leaves a cancellation to the cancellation path", async () => {
    const controller = new AbortController();
    let signal: AbortSignal | undefined;
    const cli = createCLI({ name: "test" });
    cli
      .command("deploy")
      .validate(async (ctx) => {
        signal = ctx.signal;
        await new Promise((resolve) => ctx.signal.addEventListener("abort", resolve));
        throw ctx.signal.reason;
      })
      .action(() => {});
    const execution = cli.exec(["deploy"], { ...quiet(), signal: controller.signal });
    setImmediate(() => controller.abort());
    const err = await execution.catch((e: unknown) => e);
    expect(signal?.aborted).toBe(true);
    expect(err).not.toBeInstanceOf(ValidationError);
    expect(["AbortError", "CancelledError"]).toContain((err as Error).name);
  });
});
